/**
 * @returns true if object is a string
 */
export function isString(val: any): val is string {
	return typeof val === 'string';
}

/**
 * @returns true if object is a number
 */

export function isNumber(v: any): v is number {
	return typeof v === 'number' && isFinite(v);
}

/**
 * @returns true if object is an array
 */
export function isArray(val: any): val is any[] {
	return val instanceof Array;
}

/**
 * @returns true if object is a function
 */

export function isFunction(val: any): val is Function {
	return val instanceof Function;
}

/**
 * @returns true if object is a date
 */

export function isDate(v: unknown): v is Date {
    return v instanceof Date && !isNaN(v.getTime());
}


export function isPlainObject(value: unknown): value is Record<string, any> {
  	if (typeof value !== 'object' || value === null) {
		return false;
	}

    return Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null;
}

/**
 * generic constructor definition
 */

export type Constructor<P> = {
	new(...params: any[]): P;
};


/**
 * a way to explain that the given string may be unsafe but must be treated a string
 * @example
 * label.setText( unsafehtml`<b>Bold</b> text` );
 * label.setText( new UnsafeHtml("<b>Bold</b> text`" ) );
 */

export class UnsafeHtml extends String {
	constructor(value: string) {
		super(value);
	}
}

export function unsafeHtml(x: string): UnsafeHtml {
	return new UnsafeHtml(x);
}

/**
 * you can use it recursively
 * const value = "hello";
 * const t = unsafe`<b>${ value }</b>`; // direct text
 * const result = unsafe`<i> ${ t } ${ [t,t,t] } </i>`
 * const result2 = unsafe`<i> ${ [t,t,t,"world"] } </i>`    // also mixes / array
 */

export function unsafe(strings: TemplateStringsArray, ...values: any[]): UnsafeHtml {

    const resolve = ( value: any ) : string | UnsafeHtml => {
        let v: string;
        if( !value ) {
            return "";
        }
        
        if( isArray( value ) ) {
            return value.map( resolve ).join( '' );
        }

        if ( value instanceof UnsafeHtml ) {
            return value.toString();
        }

        return sanitizeHtml(value);
    }

	const result = strings.reduce((acc, str, i) => {
        return acc + str + resolve( values[i] );
	}, '');

	return new UnsafeHtml(result);
}

/**
 * clamp a value between min/max values
 */

export function clamp<T>(v: T, min: T, max: T): T {
	if (v < min) { return min; }
	if (v > max) { return max; }
	return v;
}


/**
 * generic Rectangle 
 */

export interface IRect {
	left: number;
	top: number;
	height: number;
	width: number;
}

/**
 * 
 */

export class Rect implements IRect {
	left: number;
	top: number;
	height: number;
	width: number;

	constructor();
	constructor(l: number, t: number, w: number, h: number);
	constructor(l: Rect);
	constructor(l?: number | IRect, t?: number, w?: number, h?: number) {
		if (l !== undefined) {
			if (isNumber(l)) {
				this.left = l;
				this.top = t;
				this.width = w;
				this.height = h;
			}
			else {
				Object.assign(this, l);
			}
		}
	}

	get right() {
		return this.left + this.width;
	}

	get bottom() {
		return this.top + this.height;
	}

	contains(pt: Point): boolean;
	contains(rc: Rect): boolean;
	contains(arg: any): boolean {
		if (arg instanceof Rect) {
			return arg.left >= this.left && arg.right <= this.right && arg.top >= this.top && arg.bottom <= this.bottom;
		}
		else {
			return arg.x >= this.left && arg.x < this.right && arg.y >= this.top && arg.y < this.bottom;
		}
	}

	touches(rc: Rect): boolean {
		if (this.left > rc.right || this.right < rc.left || this.top > rc.bottom || this.bottom < rc.top) {
			return false;
		}

		return true;
	}

	normalize(): this {
		let w = this.width,
			h = this.height;

		if (w < 0) {
			this.left += w;
			this.width = -w;
		}

		if (h < 0) {
			this.top += h;
			this.height = -h;
		}

		return this;
	}

	inflate( dx: number, dy?: number ) {
		if( dy===undefined ) {
			dy = dx;
		}

		this.left -= dx;
		this.width += dx+dx;
		this.top -= dy;
		this.height += dy+dy;

		return this;
	}

	scale( scale: number ) {
		this.left *= scale;
		this.top *= scale;
		this.width *= scale;
		this.height *= scale;

		return this;
	}

    moveTo( x: number, y: number ) {
        this.left = x;
        this.top = x;

        return this;
    }
}

